// src/components/VotingPage.js
import React, { useEffect, useState, useMemo } from "react";
import axios from "axios";

const API_URL = "http://localhost:5000";

// 🔴⚪ Red & White Theme
const THEME = {
  primary: "#B11226",     // Deep Red
  primaryDark: "#8E0E1E", // Darker Red
  background: "#F8F9FA",  // Soft White Background
  white: "#FFFFFF",
  lightGray: "#E5E7EB",
  textDark: "#1F2937",
};

function VotingPage({ auth }) {
  const [candidates, setCandidates] = useState([]);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);

  const [showModal, setShowModal] = useState(false);
  const [modalMessage, setModalMessage] = useState("");
  const [modalType, setModalType] = useState("confirm");
  const [selectedCandidate, setSelectedCandidate] = useState(null);

  // Fetch candidates
  useEffect(() => {
    const fetchCandidates = async () => {
      try {
        const res = await axios.get(`${API_URL}/api/candidates`);
        setCandidates(res.data);
      } catch (error) {
        setModalMessage("Failed to load candidates.");
        setModalType("error");
        setShowModal(true);
      } finally {
        setLoading(false);
      }
    };
    fetchCandidates();
  }, []);

  const handleVote = (candidateId) => {
    if (submitting) return;
    setSelectedCandidate(candidateId);
    setModalType("confirm");
    setModalMessage("Are you sure you want to vote? This cannot be changed.");
    setShowModal(true);
  };

  const confirmVote = async () => {
    try {
      setSubmitting(true);

      await axios.post(
        `${API_URL}/api/vote/batch`,
        { candidateIds: [selectedCandidate] },
        {
          headers: {
            Authorization: `Bearer ${auth?.token}`,
          },
        }
      );

      setModalType("success");
      setModalMessage("Your vote has been successfully recorded.");
    } catch (error) {
      setModalType("error");
      setModalMessage("Vote failed or you may have already voted.");
    } finally {
      setSubmitting(false);
    }
  };

  const groupedCandidates = useMemo(() => {
    return candidates.reduce((groups, candidate) => {
      const position = candidate.candidacy;
      if (!groups[position]) groups[position] = [];
      groups[position].push(candidate);
      return groups;
    }, {});
  }, [candidates]);

  if (loading) {
    return (
      <div style={{ padding: 50, textAlign: "center" }}>
        <h2>Loading candidates...</h2>
      </div>
    );
  }

  if (candidates.length === 0) {
    return (
      <div style={{ padding: 50, textAlign: "center" }}>
        <h2>No candidates available.</h2>
      </div>
    );
  }

  return (
    <div
      style={{
        padding: 60,
        maxWidth: 1300,
        margin: "auto",
        backgroundColor: THEME.background,
        minHeight: "100vh",
      }}
    >
      {/* Page Title */}
      <h1
        style={{
          textAlign: "center",
          marginBottom: 10,
          color: THEME.primary,
          fontWeight: "800",
          letterSpacing: 1,
        }}
      >
        SorSU Student Election 2026
      </h1>

      <div
        style={{
          width: 120,
          height: 4,
          backgroundColor: THEME.primary,
          margin: "0 auto 50px auto",
          borderRadius: 2,
        }}
      />

      {Object.entries(groupedCandidates).map(([position, list]) => (
        <div key={position} style={{ marginBottom: 60 }}>
          {/* Position Header */}
          <h2
            style={{
              marginBottom: 30,
              color: THEME.primary,
              borderLeft: `6px solid ${THEME.primary}`,
              paddingLeft: 15,
              fontWeight: "700",
            }}
          >
            {position}
          </h2>

          {/* Candidates Grid */}
          <div
            style={{
              display: "flex",
              flexWrap: "wrap",
              gap: 30,
            }}
          >
            {list.map((candidate) => (
              <div
                key={candidate._id}
                style={{
                  width: 300,
                  backgroundColor: THEME.white,
                  borderRadius: 15,
                  padding: 25,
                  boxShadow: "0 15px 30px rgba(0,0,0,0.05)",
                  textAlign: "center",
                  borderTop: `5px solid ${THEME.primary}`,
                }}
              >
                {candidate.image && (
                  <img
                    src={`${API_URL}/uploads/${candidate.image}`}
                    alt={`${candidate.firstName} ${candidate.lastName}`}
                    style={{
                      width: "100%",
                      height: 220,
                      objectFit: "cover",
                      borderRadius: 10,
                      marginBottom: 15,
                      border: `3px solid ${THEME.primary}`,
                    }}
                  />
                )}

                <h3 style={{ color: THEME.textDark, marginBottom: 8 }}>
                  {candidate.firstName} {candidate.lastName}
                </h3>

                <p style={{ fontSize: 14, color: "#555" }}>
                  {candidate.yearLevel} - {candidate.block}
                </p>

                <p
                  style={{
                    fontSize: 14,
                    minHeight: 50,
                    color: "#666",
                  }}
                >
                  Partylist: {candidate.partylist || "Independent"}
                </p>

                <button
                  onClick={() => handleVote(candidate._id)}
                  disabled={submitting}
                  style={{
                    marginTop: 20,
                    padding: "12px",
                    width: "100%",
                    backgroundColor: THEME.primary,
                    color: "#fff",
                    border: "none",
                    borderRadius: 8,
                    fontWeight: "600",
                    cursor: "pointer",
                    transition: "0.3s",
                  }}
                  onMouseOver={(e) =>
                    (e.target.style.backgroundColor = THEME.primaryDark)
                  }
                  onMouseOut={(e) =>
                    (e.target.style.backgroundColor = THEME.primary)
                  }
                >
                  Vote
                </button>
              </div>
            ))}
          </div>
        </div>
      ))}

      {/* MODAL */}
      {showModal && (
        <div style={modalStyles.overlay}>
          <div style={modalStyles.modal}>
            <h3 style={{ marginBottom: 20, color: THEME.primary }}>
              {modalType === "confirm"
                ? "Confirm Your Vote"
                : modalType === "success"
                ? "Vote Successful"
                : "Error"}
            </h3>

            <p style={{ marginBottom: 30 }}>{modalMessage}</p>

            {modalType === "confirm" ? (
              <div style={{ display: "flex", justifyContent: "space-between" }}>
                <button
                  style={modalStyles.cancel}
                  onClick={() => setShowModal(false)}
                >
                  Cancel
                </button>

                <button
                  style={modalStyles.confirm}
                  onClick={confirmVote}
                  disabled={submitting}
                >
                  {submitting ? "Submitting..." : "Confirm"}
                </button>
              </div>
            ) : (
              <button
                style={modalStyles.confirm}
                onClick={() => setShowModal(false)}
              >
                OK
              </button>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

const modalStyles = {
  overlay: {
    position: "fixed",
    top: 0,
    left: 0,
    width: "100%",
    height: "100%",
    backgroundColor: "rgba(0,0,0,0.6)",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    zIndex: 999,
  },
  modal: {
    width: 380,
    backgroundColor: "#ffffff",
    padding: 35,
    borderRadius: 12,
    textAlign: "center",
    boxShadow: "0 15px 35px rgba(0,0,0,0.2)",
  },
  cancel: {
    padding: "10px 20px",
    border: "none",
    backgroundColor: "#ccc",
    borderRadius: 6,
    cursor: "pointer",
  },
  confirm: {
    padding: "10px 20px",
    border: "none",
    backgroundColor: "#B11226",
    color: "#fff",
    borderRadius: 6,
    cursor: "pointer",
  },
};

export default VotingPage;
